import os, re
def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_raw = t[m.end():].split('\n')[:h]
        rows = [r.split() for r in rows_raw if r.strip()]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G
G = load()

test_input = G['Test input']

# Find single-color rows in test
marker_rows_test = []
for r in range(len(test_input)):
    row_vals = set(test_input[r])
    if len(row_vals) == 1:
        marker_rows_test.append((r, list(test_input[r])[0]))
print(f"Single-color rows in test: {marker_rows_test}")

# Find leftmost and rightmost non-background columns per row
bg_color = 1
for r in range(len(test_input)):
    cols_with_other = []
    for c in range(len(test_input[0])):
        if test_input[r][c] != bg_color:
            cols_with_other.append(c)
    if cols_with_other:
        print(f"Row {r}: first non-bg col={min(cols_with_other)}, last non-bg col={max(cols_with_other)}")

# Maybe the vertical line is between two regions?
# Let me find transitions in each row
print("\n=== Row-by-row transition analysis ===")
for r in range(min(5, len(test_input))):  # Just first few rows
    transitions = []
    for c in range(len(test_input[0]) - 1):
        if test_input[r][c] != test_input[r][c+1]:
            transitions.append(c)
    print(f"Row {r} transitions: {transitions}")

# And a row in the middle of the shape
for r in range(16, 22):  # The shape area
    transitions = []
    for c in range(len(test_input[0]) - 1):
        if test_input[r][c] != test_input[r][c+1]:
            transitions.append(c)
    print(f"Shape row {r} transitions: {transitions}")

